  for (final problem in result.problems) {
    stdout.writeln('  ✗ $problem');
  }
  if (!result.ok) {
    stderr.writeln(
      'agents-gate RED: ${result.problems.length} merge problem(s) — '
      'the suite partition is broken or a shard is red',
    );
    exit(1);

